 "content": "def transform(grid):
    a=[r[:] for r in grid]; n=len(a)
    # Each color stripe is a vertical line joining matching colored endpoints/bars.
    # identify columns with repeated color markers and fill vertical between extremes
    for c in range(len(a[0])):
        vals=[(r,a[r][c]) for r in range(n) if a[r][c]]
        colors={v for r,v in vals}
        for color in colors:
            rows=[r for r,v in vals if v==color]
            if len(rows)>=2:
                for r in range(min(rows),max(rows)+1):
                    if a[r][c]==0: a[r][c]=color
    return a
